import{_ as t,l as i,o as a,c as l,v as o,p as h,x as r,d as n,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Needham–Schroeder 与 Lowe","description":"","frontmatter":{"title":"Needham–Schroeder 与 Lowe","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/needham-schroeder-lowe.md","filePath":"cs/needham-schroeder-lowe.md","lastUpdated":1789023840000}'),p={name:"cs/needham-schroeder-lowe.md"};function m(A,e,E,_,B,u){const d=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="needham–schroeder-与-lowe" tabindex="-1">Needham–Schroeder 与 Lowe <a class="header-anchor" href="#needham–schroeder-与-lowe" aria-label="Permalink to &quot;Needham–Schroeder 与 Lowe&quot;">​</a></h1><div class="epigraph"><p>Needham–Schroeder 公钥协议看起来互相证明了新鲜 nonce；Lowe 指出缺少身份绑定，第三者可以把会话转包。修复是在消息里显式写上对端名字。</p><footer>—— Needham and Schroeder, 1978；Lowe, Breaking and Fixing the Needham-Schroeder Public-Key Protocol, TACAS 1996</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/protocol-verification">ProVerif/Tamarin</a>要一个经典标本。缺口就是 <strong>NS 公钥协议与 Lowe 修正</strong>：认证对应性失败的最小例子。软件安全下一单元从这里离开协议逻辑，进入内存。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>A 与 B 交换加密 nonce。攻击者 I 让 A 以为在和 I 谈，同时让 B 以为在和 A 谈——只陈述身份错绑。Lowe：在加密载荷里加入对端身份。缺口是「认证要钉住是谁」，不是 nonce 算术作业。</p><h3 id="符号攻击-实现包" tabindex="-1">符号攻击≠实现包 <a class="header-anchor" href="#符号攻击-实现包" aria-label="Permalink to &quot;符号攻击≠实现包&quot;">​</a></h3><p>本课不给报文级利用。要的是：设计时把身份放进认证消息，再用工具查对应性。</p><p><span class="marginnote">Needham–Schroeder 1978 还有对称密钥版与服务器。Lowe 1996 针对公钥版。这是协议验证课的标准例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写三消息形状与 Lowe 的字段补丁。对照 TLS 的签名 Finished 与证书名：同一思想——名字绑进密钥交换。指出软件漏洞不在此模型里。</p>',12)),(a(),h(c,null,{default:r(()=>[s(d,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS%5B%22NS%20%E5%85%AC%E9%92%A5%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20GAP%5B%22%E8%BA%AB%E4%BB%BD%E6%9C%AA%E7%BB%91%E8%BF%9B%E5%AF%86%E6%96%87%22%5D%0A%20%20GAP%20--%3E%20CONF%5B%22%E5%AF%B9%E5%BA%94%E6%80%A7%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20LOWE%5B%22%E5%AF%86%E6%96%87%E5%86%85%E5%86%99%E5%85%A5%E5%AF%B9%E7%AB%AF%E5%90%8D%22%5D%20--%3E%20FIX%5B%22Lowe%20%E4%BF%AE%E6%AD%A3%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>身份单元封口：令牌、会话、联邦、因素、形式化，最后用 NSL 说明最小补丁。下一课程单元软件安全：栈上的比特如何破坏「进程按源码语义执行」这一假设。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Kerberos 全部消息重写（Windows 课更后）。下一课栈溢出到 shellcode：空间安全的开口，只讲机制与防御，不给可运行载荷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具课需要标本：NS 公钥协议的认证洞。</li><li>Lowe：把对端身份写进认证密文。</li><li>对应性是「谁与谁完成了会话」。</li><li>下一单元：栈溢出与内存破坏（防御视角）。</li><li>出处：Needham and Schroeder, 1978；Lowe, 1996。</li></ul>',8))])}const w=t(p,[["render",m]]);export{f as __pageData,w as default};
